```javascript
// 設定画面の初期化
function initSettings() {
    const settingsBtn = document.createElement('button');
    settingsBtn.id = 'settingsBtn';
    settingsBtn.innerHTML = '<i class="fas fa-cog"></i> 設定';
    settingsBtn.className = 'settings-btn';
    document.querySelector('.app-header').appendChild(settingsBtn);

    settingsBtn.addEventListener('click', () => {
        document.getElementById('settingsModal').style.display = 'block';
        loadCurrentCriteria();
    });

    document.getElementById('closeSettings').addEventListener('click', () => {
        document.getElementById('settingsModal').style.display = 'none';
    });

    document.getElementById('criteriaForm').addEventListener('submit', (e) => {
        e.preventDefault();
        saveCriteria();
    });

    document.getElementById('addExpressionItem').addEventListener('click', () => {
        addCriteriaItem('expression');
    });

    document.getElementById('addVoiceItem').addEventListener('click', () => {
        addCriteriaItem('voice');
    });
}

// 現在の評価項目を読み込む
function loadCurrentCriteria() {
    fetch('/api/criteria')
        .then(response => response.json())
        .then(criteria => {
            document.getElementById('expressionWeight').value = criteria.prompt.criteria.expression.weight;
            document.getElementById('voiceWeight').value = criteria.prompt.criteria.voice.weight;

            const expressionItems = document.getElementById('expressionItems');
            expressionItems.innerHTML = '';
            criteria.prompt.criteria.expression.items.forEach(item => {
                addCriteriaItem('expression', item);
            });

            const voiceItems = document.getElementById('voiceItems');
            voiceItems.innerHTML = '';
            criteria.prompt.criteria.voice.items.forEach(item => {
                addCriteriaItem('voice', item);
            });
        })
        .catch(error => {
            console.error('評価項目の読み込みに失敗しました:', error);
        });
}

// 評価項目を追加する
function addCriteriaItem(type, value = '') {
    const container = document.getElementById(`${type}Items`);
    const itemDiv = document.createElement('div');
    itemDiv.className = 'criteria-item';

    const input = document.createElement('input');
    input.type = 'text';
    input.value = value;
    input.placeholder = '項目を入力';

    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'remove-btn';
    removeBtn.innerHTML = '<i class="fas fa-times"></i>';
    removeBtn.addEventListener('click', () => {
        container.removeChild(itemDiv);
    });

    itemDiv.appendChild(input);
    itemDiv.appendChild(removeBtn);
    container.appendChild(itemDiv);
}

// 評価項目を保存する
function saveCriteria() {
    const criteria = {
        prompt: {
            criteria: {
                expression: {
                    weight: parseInt(document.getElementById('expressionWeight').value),
                    items: Array.from(document.querySelectorAll('#expressionItems input')).map(input => input.value)
                },
                voice: {
                    weight: parseInt(document.getElementById('voiceWeight').value),
                    items: Array.from(document.querySelectorAll('#voiceItems input')).map(input => input.value)
                }
            }
        }
    };

    fetch('/api/criteria', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify(criteria)
    })
    .then(response => response.json())
    .then(data => {
        alert('設定が保存されました');
        document.getElementById('settingsModal').style.display = 'none';
    })
    .catch(error => {
        console.error('設定の保存に失敗しました:', error);
        alert('設定の保存に失敗しました');
    });
}
